-- ONEPILOT V7 — référentiel partagé RH / Projets issu de la bibliothèque v2 N0 à N4.
create extension if not exists pgcrypto;

alter table if exists public.hr_skill_catalog
  add column if not exists chapter_code text,
  add column if not exists subchapter_code text,
  add column if not exists level_evidence jsonb not null default '{}'::jsonb,
  add column if not exists source_version text;

alter table if exists public.hr_skill_catalog
  drop constraint if exists hr_skill_catalog_organization_id_name_key;

create unique index if not exists hr_skill_catalog_org_code_uq
  on public.hr_skill_catalog(organization_id, code)
  where code is not null;

alter table if exists public.project_skill_requirements
  add column if not exists skill_chapter text,
  add column if not exists skill_subchapter text;

create index if not exists hr_skill_catalog_chapter_idx
  on public.hr_skill_catalog(organization_id, chapter_code, subchapter_code, code)
  where archived_at is null;

create temporary table onepilot_skill_seed (
  chapter_code text not null,
  chapter_name text not null,
  subchapter_code text not null,
  subchapter_name text not null,
  skill_code text not null,
  skill_name text not null,
  description text,
  level_expectations jsonb not null
) on commit drop;


  organization_id, code, name, family, category, description, criticality,
  is_active, level_expectations, chapter_code, subchapter_code, level_evidence,
  source_version, archived_at, updated_at
)
select organization.id, seed.skill_code, seed.skill_name, seed.chapter_name, seed.subchapter_name,
  seed.description,
  case when seed.chapter_name in ('Certifs & Habilitations', 'Qualité & HSE', 'IT & Cyber') then 'important' else 'standard' end,
  true, seed.level_expectations, seed.chapter_code, seed.subchapter_code,
  jsonb_build_object(
    '0', 'Aucune expérience ou connaissance déclarée.',
    '1', 'Formation initiale, exercice simple ou réalisation accompagnée.',
    '2', 'Livrables courants conformes après revue et mise en pratique répétée.',
    '3', 'Livrables acceptés sans supervision rapprochée et situations courantes maîtrisées.',
    '4', 'Deux preuves minimum : cas complexe, standard amélioré, tutorat ou gain mesurable.'
  ),
  'bibliotheque_competences_v2_niveaux_0_4', null, now()
from public.organizations organization
cross join onepilot_skill_seed seed
on conflict (organization_id, code) where code is not null do update set
  code = excluded.code,
  family = excluded.family,
  category = excluded.category,
  description = excluded.description,
  criticality = excluded.criticality,
  is_active = true,
  level_expectations = excluded.level_expectations,
  chapter_code = excluded.chapter_code,
  subchapter_code = excluded.subchapter_code,
  level_evidence = excluded.level_evidence,
  source_version = excluded.source_version,
  archived_at = null,
  updated_at = now();

-- La table historique hr_employee_skills référence encore hr_skills dans les bases existantes.
-- Les deux référentiels utilisent donc exactement le même identifiant afin de préserver les FK,
-- le staffing existant et la nouvelle bibliothèque RH / Projets.
  id, organization_id, code, name, description, skill_type, is_active, updated_at
)
select catalog.id, catalog.organization_id, catalog.code, catalog.name,
  'Compétence synchronisée depuis le référentiel unique RH / Projets.',
  case
    when catalog.family in ('IT & Cyber', 'Logiciel & Data', 'Mécanique', 'Électronique') then 'technical'
    when catalog.family = 'Certifs & Habilitations' then 'certification'
    when catalog.family = 'Transverse' and catalog.category = 'Langues' then 'language'
    when catalog.family in ('Projet & PMO', 'Qualité & HSE') then 'methodology'
    when catalog.family = 'RH' then 'management'
    else 'functional'
  end,
  true, now()
from public.hr_skill_catalog catalog
where catalog.source_version = 'bibliotheque_competences_v2_niveaux_0_4'
  and not exists (select 1 from public.hr_skills legacy where legacy.id = catalog.id)
on conflict (organization_id, code) do update set
  name = excluded.name,
  description = excluded.description,
  skill_type = excluded.skill_type,
  is_active = true,
  updated_at = now();

-- Si un code historique existait déjà avec un autre identifiant, réaligner le catalogue sur
-- l'identifiant réellement porté par la FK de hr_employee_skills avant toute démonstration.
update public.project_skill_requirements requirement
set skill_id = legacy.id, updated_at = now()
from public.hr_skills legacy
where legacy.organization_id = requirement.organization_id
  and legacy.code = requirement.skill_code
  and requirement.skill_id is distinct from legacy.id;

-- Recalage des besoins projet sur le référentiel commun, sans dépendre de l’activation du module RH.
update public.project_skill_requirements requirement
set skill_id = legacy.id,
    skill_code = catalog.code,
    skill_name = catalog.name,
    skill_family = catalog.family || ' / ' || catalog.category,
    skill_chapter = catalog.family,
    skill_subchapter = catalog.category,
    updated_at = now()
from public.hr_skill_catalog catalog
join public.hr_skills legacy
  on legacy.organization_id = catalog.organization_id
 and legacy.code = catalog.code
where catalog.organization_id = requirement.organization_id
  and catalog.archived_at is null
  and (lower(catalog.name) = lower(requirement.skill_name) or lower(catalog.code) = lower(coalesce(requirement.skill_code, '')));

-- Démonstration cohérente : besoins projet et niveaux réels des ressources affectées.
do $$
declare
  project_row record;
  skill_row record;
  employee_row record;
  skill_index integer;
  employee_index integer;
  required_level_value integer;
  actual_level integer;
  requirement_id uuid;
begin
  for project_row in
    select project.id, project.organization_id, project.code
    from public.project_projects project
    where project.archived_at is null
    order by project.organization_id, project.code
    limit 12
  loop
    skill_index := 0;
    for skill_row in
      select catalog.*, legacy.id as compatible_skill_id
      from public.hr_skill_catalog catalog
      join public.hr_skills legacy
        on legacy.organization_id = catalog.organization_id
       and legacy.code = catalog.code
      where catalog.organization_id = project_row.organization_id
        and catalog.archived_at is null
        and ((catalog.family = 'Projet & PMO' and catalog.category in ('Planning', 'Coûts & risques', 'Pilotage'))
          or (catalog.family = 'Qualité & HSE' and catalog.name in ('Audit projet', 'Gestion des risques')))
      order by catalog.code
      limit 8
    loop
      skill_index := skill_index + 1;
      required_level_value := case when skill_index in (2, 5) then 4 when skill_index in (1, 3, 6) then 3 else 2 end;
      select requirement.id into requirement_id
      from public.project_skill_requirements requirement
      where requirement.organization_id = project_row.organization_id
        and requirement.project_id = project_row.id
        and requirement.task_id is null
        and lower(requirement.skill_name) = lower(skill_row.name)
      limit 1;

      if requirement_id is null then
          organization_id, project_id, skill_id, skill_code, skill_name, skill_family,
          skill_chapter, skill_subchapter, required_level, minimum_people, importance,
          planned_hours, coverage_percent, justification, archived_at, updated_at
        ) values (
          project_row.organization_id, project_row.id, skill_row.compatible_skill_id, skill_row.code, skill_row.name,
          skill_row.family || ' / ' || skill_row.category, skill_row.family, skill_row.category,
          required_level_value, case when required_level_value >= 4 then 1 else 2 end,
          case when required_level_value >= 4 then 'critical' when required_level_value = 3 then 'required' else 'useful' end,
          35 + skill_index * 9, 0,
          'Besoin démonstration synchronisé avec le référentiel unique RH / Projets.', null, now()
        );
      else
        update public.project_skill_requirements set
          skill_id = skill_row.compatible_skill_id, skill_code = skill_row.code,
          skill_family = skill_row.family || ' / ' || skill_row.category,
          skill_chapter = skill_row.family, skill_subchapter = skill_row.category,
          required_level = required_level_value,
          minimum_people = case when required_level_value >= 4 then 1 else 2 end,
          importance = case when required_level_value >= 4 then 'critical' when required_level_value = 3 then 'required' else 'useful' end,
          planned_hours = 35 + skill_index * 9,
          justification = 'Besoin démonstration synchronisé avec le référentiel unique RH / Projets.',
          archived_at = null, updated_at = now()
        where id = requirement_id;
      end if;

      employee_index := 0;
      for employee_row in
        select distinct assignment.employee_id
        from public.project_task_assignments assignment
        where assignment.organization_id = project_row.organization_id
          and assignment.project_id = project_row.id
          and assignment.employee_id is not null
          and assignment.archived_at is null
        order by assignment.employee_id
        limit 8
      loop
        employee_index := employee_index + 1;
        actual_level := greatest(0, least(4, required_level_value - ((employee_index + skill_index) % 3)));
          organization_id, employee_id, skill_id, level, current_level, target_level,
          assessment_date, evidence, project_context, last_self_assessment_at,
          assessor_type, status, archived_at, updated_at
        ) values (
          project_row.organization_id, employee_row.employee_id, skill_row.compatible_skill_id,
          actual_level, actual_level, required_level_value, current_date - ((employee_index + skill_index) * 7),
          case when actual_level >= required_level_value then 'Livrable projet accepté sans reprise.' else 'Auto-évaluation à confirmer par le manager et une preuve projet.' end,
          project_row.code || ' · comparaison besoin projet / niveau ressource', current_date,
          'manager', case when actual_level >= required_level_value then 'validated' else 'to_develop' end,
          null, now()
        ) on conflict (organization_id, employee_id, skill_id) do update set
          level = excluded.level, current_level = excluded.current_level,
          target_level = greatest(public.hr_employee_skills.target_level, excluded.target_level),
          assessment_date = excluded.assessment_date, evidence = excluded.evidence,
          project_context = excluded.project_context, assessor_type = excluded.assessor_type,
          status = excluded.status, archived_at = null, updated_at = now();
      end loop;
    end loop;
  end loop;

  update public.project_skill_requirements requirement
  set coverage_percent = coalesce(coverage.coverage_percent, 0), updated_at = now()
  from (
    select requirement_inner.id,
      round(100.0 * count(distinct assignment.employee_id) filter (where coalesce(employee_skill.current_level, employee_skill.level, 0) >= requirement_inner.required_level)
        / nullif(count(distinct assignment.employee_id), 0), 2) as coverage_percent
    from public.project_skill_requirements requirement_inner
    left join public.project_task_assignments assignment
      on assignment.organization_id = requirement_inner.organization_id
      and assignment.project_id = requirement_inner.project_id
      and assignment.employee_id is not null and assignment.archived_at is null
    left join public.hr_employee_skills employee_skill
      on employee_skill.organization_id = requirement_inner.organization_id
      and employee_skill.employee_id = assignment.employee_id
      and employee_skill.skill_id = requirement_inner.skill_id
      and employee_skill.archived_at is null
    where requirement_inner.archived_at is null
    group by requirement_inner.id
  ) coverage
  where requirement.id = coverage.id;
end;
$$;
